var n=`0698-gboma-dessi`;var t=`world-0698`;var s=`TG`;var a=`western-africa`;var o=4;var r=59;var g={en:`Gboma Dessi`,ua:`Гбома дессі`};var h={en:`Gboma Dessi is a Togo classic prepared with beef chuck, yellow onion, spinach, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Гбома дессі, страва кухні країни Того зі складниками: яловича лопатка, жовта цибуля, шпинат, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var l=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`beef-chuck`,500,`g`],[`red-palm-oil`,50,`ml`],[`yellow-onion`,170,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 45 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 45 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:45,i:[[`spinach`,430,`g`],[`tomato`,260,`g`],[`water`,500,`ml`],[`crayfish`,100,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`ground-cumin`,4,`g`]]}];var m={slug:n,id:t,country:`TG`,region:a,servings:4,minutes:59,title:g,text:h,steps:l};export{s as country,m as default,t as id,r as minutes,a as region,o as servings,n as slug,l as steps,h as text,g as title};